def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['target_taken'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['target_taken'] = False
    if target and act.startswith('put ') and target not in act and 'you put' in obs:
        nb['wrong_put'] = True
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs:
        nb['transformed'] = True
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        pc = max(pc, 1)
    nb['placed_count'] = pc
    need = 2 if 'two' in tt else 1
    carrying = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    if target and act.startswith('put ') and target in act and 'you put' in obs and dest and dest in act:
        carrying = False
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        carrying = True
    wrong = bool(target and inv and 'not carrying' not in inv and 'nothing' not in inv and target not in inv)
    if wrong:
        stage = 'wrong_inventory'
    elif not target:
        stage = 'find_target'
    elif not carrying:
        stage = 'take_target' if (target in obs or getv(ctx, 'world.target_found', False)) else 'find_target'
    elif verb and not nb.get('transformed'):
        stage = 'transform'
    elif dest and not (act.startswith('put ') and dest in act and 'you put' in obs):
        stage = 'go_destination'
    else:
        stage = 'put_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

