def hook(ctx, nb):
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type') or text(getv(ctx, 'task.task_type', '')))
    stage = nb.get('stage') or 'find_target'
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory appears to hold a non-target item. Do not place it as the goal object; recover by setting it aside only if needed, then search for the requested target type.'
    elif stage == 'take_target' and target:
        msg = 'A requested target type is available here. Take the target instead of continuing to search or taking a different object.'
    elif stage == 'transform' and target and verb:
        msg = 'You are carrying the target. Use the required ' + verb + ' action before placing it at the destination.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the target to the requested destination type ' + dest + ' and put it there; do not put it on other surfaces.'
    elif stage == 'put_target' and target and dest:
        msg = 'At the destination, use the put action for the target at ' + dest + '. After placing, do not take it back or loop on look/inventory.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

